{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "What is the last date to apply for Varun Vihar Yojana?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Registration for the 2,847 Phase 1 plots is open from 24 September to 24 October 2026 on registration.ldalucknow.in."
      }
    },
    {
      "@type": "Question",
      "name": "What is the plot price in Varun Vihar?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "LDA has fixed the rate at ₹2,800 per sq ft. A 112.5 sq m plot costs about ₹33.9 lakh and a 450 sq m plot about ₹1.36 crore. Corner/park-facing charges and the 12% freehold charge are extra."
      }
    },
    {
      "@type": "Question",
      "name": "How much money do I need to deposit to register?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "After the ₹1,100 booklet, you deposit 5% of the plot price (2.5% for reserved categories). For a 112.5 sq m plot this is about ₹1.7 lakh."
      }
    },
    {
      "@type": "Question",
      "name": "Is there any benefit in paying the full amount at once?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. Paying in full within 45 days gives a 6% discount, within 60 days 5% and within 90 days 4%. According to Bhaskar Digital, the lottery for full-payment applicants will be drawn first."
      }
    },
    {
      "@type": "Question",
      "name": "Where is Varun Vihar in Lucknow?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Near the Agra–Lucknow Expressway, in Sadar and Sarojini Nagar tehsils. The expressway lies to the north of the scheme and the Fatehganj–Mohan Road to the south."
      }
    },
    {
      "@type": "Question",
      "name": "Which villages are in Varun Vihar?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "According to LDA, 12 villages: Bhaliya, Adampur Indwara, Bahru, Jaliyamau, Madarpur, Ibrahimganj, Naktaura, Gahlwara, Tejkrishna Khera, Rewari, Sakra and Dona."
      }
    },
    {
      "@type": "Question",
      "name": "Which blocks have plots in Phase 1?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Kashi Khand, Kailash Khand Phase 1 and Kailash Khand Phase 2 have 2,847 plots in total — 1,517 of 112.5 sq m, 460 of 162, 612 of 200, 68 of 288, 81 of 300 and 109 of 450 sq m."
      }
    },
    {
      "@type": "Question",
      "name": "Who can apply for Varun Vihar?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "According to Amar Ujala, anyone aged 18 or above who has not been allotted a plot or house earlier by LDA or any housing authority. The full conditions are in LDA's booklet."
      }
    }
  ]
}

